// HasAPIKey applies the HasEdge predicate on the "api_key" edge.
func HasAPIKey() predicate.EvaluationRouteEvidence {
	return predicate.EvaluationRouteEvidence(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, APIKeyTable, APIKeyColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAPIKeyWith applies the HasEdge predicate on the "api_key" edge with a given conditions (other predicates).
func HasAPIKeyWith(preds ...predicate.APIKey) predicate.EvaluationRouteEvidence {
	return predicate.EvaluationRouteEvidence(func(s *sql.Selector) {
		step := newAPIKeyStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EvaluationRouteEvidence) predicate.EvaluationRouteEvidence {
	return predicate.EvaluationRouteEvidence(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EvaluationRouteEvidence) predicate.EvaluationRouteEvidence {
	return predicate.EvaluationRouteEvidence(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EvaluationRouteEvidence) predicate.EvaluationRouteEvidence {
	return predicate.EvaluationRouteEvidence(sql.NotPredicates(p))
}
